import os
import torch
import random
import numpy as np


class Config:
    # --------------------------------------------------------------------------
    # Directory & File Paths
    # --------------------------------------------------------------------------
    INPUT_DIR = "./input"
    TRAIN_DIR = os.path.join(INPUT_DIR, "train")
    TEST_DIR = os.path.join(INPUT_DIR, "test")

    # Metadata generated by the provided script
    METADATA_DIR = "./metadata"
    TRAIN_METADATA = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA = os.path.join(METADATA_DIR, "test.csv")

    # Output Directories
    WORKING_DIR = "./working"
    # Specific cache directory for this idea as requested
    CACHE_DIR = os.path.join(WORKING_DIR, "idea_42")
    MODEL_SAVE_PATH = os.path.join(CACHE_DIR, "best_model.pth")

    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # --------------------------------------------------------------------------
    # Data & Preprocessing Hyperparameters
    # --------------------------------------------------------------------------
    IMG_SIZE = 224

    # Stack Configuration: [Anchor-5, Anchor, Anchor+5]
    NUM_SLICES_PER_STACK = 3
    STACK_STRIDE = 5

    # Modalities: FLAIR, T1w, T1wCE, T2w
    NUM_MODALITIES = 4

    # Total input channels = Modalities * Slices (4 * 3 = 12)
    NUM_CHANNELS = NUM_MODALITIES * NUM_SLICES_PER_STACK

    # Multi-Instance Learning (MIL) Candidate Generation
    NUM_CANDIDATES = 3  # Top-3 Local Maxima
    CANDIDATE_MIN_DIST = 10  # Minimum slice distance between peaks
    SEARCH_MIN_DEPTH = 0.15  # Ignore first 15% of volume
    SEARCH_MAX_DEPTH = 0.85  # Ignore last 15% of volume

    # --------------------------------------------------------------------------
    # Training Hyperparameters
    # --------------------------------------------------------------------------
    SEED = 42
    BATCH_SIZE = 32
    NUM_EPOCHS = 20

    # Optimization
    LEARNING_RATE = 1e-4
    WEIGHT_DECAY = 1e-2
    PATIENCE = 5  # Early stopping patience

    # --------------------------------------------------------------------------
    # Compute
    # --------------------------------------------------------------------------
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4  # Optimized for the 12 vCPUs available

    @staticmethod
    def setup():
        """Ensures necessary working directories exist."""
        os.makedirs(Config.CACHE_DIR, exist_ok=True)
        os.makedirs(Config.SUBMISSION_DIR, exist_ok=True)


def seed_everything(seed=Config.SEED):
    """Sets random seeds for reproducibility."""
    random.seed(seed)
    os.environ["PYTHONHASHSEED"] = str(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed(seed)
    torch.backends.cudnn.deterministic = True
    torch.backends.cudnn.benchmark = False


# Initialize directories on module import
Config.setup()
